import pandas as pd
import glob
import io

def load_farm_df(f):
    with open(f, 'rb') as fp:
        raw = fp.read()

    if raw.startswith(b'\xff\xfe') or raw.startswith(b'\xfe\xff'):
        text = raw.decode('utf-16')
    else:
        text = raw.decode('utf-8', errors='ignore')

    lines = text.splitlines()
    data_lines = [l for l in lines if 'Generated:' not in l and 'Status:' not in l and 'System Export Report' not in l]

    if not data_lines:
        return pd.DataFrame()

    header = data_lines[0]
    if ';' in header:
        sep = ';'
    else:
        sep = ','

    first_data_line = data_lines[1]
    decimal = '.'
    if sep == ';' and ',' in first_data_line:
        decimal = ','

    df = pd.read_csv(io.StringIO('\n'.join(data_lines)), sep=sep, decimal=decimal)
    rename_cols = {col: col.replace('\t', '') for col in df.columns}
    df.rename(columns=rename_cols, inplace=True)
    return df

for f in sorted(glob.glob('/app/dataset/production_FARM_*.csv'))[:5]:
    df = load_farm_df(f)
    print(f, df['timestamp'].head(1).tolist(), df.columns.tolist()[-2:])
